public void checkItems()
{
    AVASCMItemState     avaSCMItemState = KCS_KAOItemStateTable.ItemState;
    KCS_KAOItemStateTable.ItemState = 'Unknown999';
    next checkItems();

    KCS_KAOItemStateTable.ItemState = avaSCMItemState;
    AVAAVASCMItemStateUpdateV2::runItemState(KCS_KAOItemStateTable,false);

}
